# Darshan guides ("मंदिर दर्शन गाइड"): one hub page + one page per big temple, answering what devotees search
# before a visit — timings, ticket/booking (official links only), helicopter/ropeway, rules, how to reach, crowd, FAQ.
# Facts checked on 26 Oct 2026 against the temple trust / government source where one could be read
# (otherwise against dated news reports); every page tells readers to confirm on the official site.
# Executed inside build.py after guides_section (uses add, band, sec_head, faq_html, faq_ld, e, SITE, PAGES, LIVE).

DG_CHECKED = "26 अक्टूबर 2026"
DG_HUB = "mandir-darshan-guide.html"
_LIVE_BY = {x[0]: x for x in LIVE}

def _dg_table(head, rows):
    th = "".join(f"<th>{e(h)}</th>" for h in head)
    tr = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return f'<div class="tbl"><table class="ptable"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>'

def _dg_list(items):
    return '<ul class="dg-list">' + "".join(f"<li>{x}</li>" for x in items) + "</ul>"

def _ext(url, label=None):
    return f'<a href="{url}" target="_blank" rel="noopener">{label or url.split("//",1)[-1].rstrip("/")}</a>'

def _dg_player(live_slug, name):
    d = _LIVE_BY.get(live_slug)
    if not d: return ""
    cid, cname, note = d[3], d[4], d[5]
    aud = _aud(live_slug) if "_aud" in globals() else ""
    return (f'<div class="ld-player dg-player" data-ch="{cid}" data-t="{e(name)} लाइव दर्शन" data-aud="{aud}"><div class="ld-frame">'
            f'<img src="img/live/sm/{live_slug}.webp" alt="{e(name)}" width="300" height="300" loading="lazy">'
            f'<button class="ld-start" type="button"><span>▶ {e(name)} — दर्शन शुरू करें</span></button></div>'
            '<div class="ld-modes" role="group" aria-label="क्या देखें"><button class="chip" data-mode="recent" aria-pressed="false">दर्शन और आरती</button>'
            '<button class="chip live-chip" data-mode="live" aria-pressed="false"><span class="lv-dot" aria-hidden="true"></span>अभी लाइव देखें</button></div>'
            '<div class="bh-aud dg-aud"></div>'
            f'<p class="note">स्रोत: मंदिर का आधिकारिक YouTube चैनल “{e(cname)}” — {e(note)}। वीडियो के सभी अधिकार उन्हीं के हैं। '
            f'<a href="live-darshan.html#{live_slug}">सभी मंदिरों के लाइव दर्शन</a></p></div>')

