import re as _re
def _dg_name(r):
    if "#" in r:
        d = _LIVE_BY.get(r.split("#")[1]); return (d[1] + " लाइव") if d else r
    m = _re.search(r"<title>([^<]+)</title>", PAGES.get(r, ""))
    t = m.group(1) if m else r
    return _re.split(r" — | \| | – |: ", t)[0].strip()

# ---- render the temple pages ----
_dg_built = []
for g in DARSHAN:
    secs = []
    if g["live"]:
        secs.append('<h2 class="k-h">आज के लाइव दर्शन</h2>' + _dg_player(g["live"], g["name"]))
    for s in g["sections"]:
        h, kind = s[0], s[1]
        if kind == "{T}":
            _sh = _dg_table(s[2], s[3]) + (f'<p class="pc-note">{s[4]}</p>' if len(s) > 4 and s[4] else "")
        elif kind == "{L}":
            _sh = _dg_list(s[2])
        else:
            _sh = f"<p>{s[2]}</p>"
        secs.append('<h2 class="k-h">' + e(h) + "</h2>" + _sh)
    off = (f'आधिकारिक वेबसाइट: {_ext(g["official"])}। ' if g["official"] else "")
    secs.append(f'<p class="pc-note">जानकारी की जाँच: {g.get('checked', DG_CHECKED)}। {off}मंदिर समय, शुल्क और नियम बदलते रहते हैं — यात्रा या भुगतान से पहले आधिकारिक वेबसाइट पर ज़रूर देखें।</p>')
    rel = [r for r in g["rel"] if r.split("#")[0] in PAGES]
    others = [o for o in DARSHAN if o["slug"] != g["slug"]]
    more = ('<ul class="library">' + "".join(f'<li><a href="{o["slug"]}"><strong>{e(o["short"])}</strong><span>दर्शन गाइड</span></a></li>' for o in others)
            + f'<li><a href="{DG_HUB}"><strong>सभी मंदिर</strong><span>दर्शन गाइड</span></a></li></ul>')
    read = ('<ul class="library">' + "".join(f'<li><a href="{r}"><strong>{e(_dg_name(r))}</strong><span>पढ़ें और सुनें</span></a></li>' for r in rel) + "</ul>") if rel else ""
    body = (band(g["h1"], g["answer"], g["crumb"] if "crumb" in g else g["short"] + " दर्शन") +
            '<article><section><div class="wrap prose katha dg-page">' + "".join(secs) + "</div></section></article>" +
            (('<section class="no-print"><div class="wrap">' + sec_head("साथ में पढ़ें") + read + "</div></section>") if read else "") +
            '<section class="band no-print"><div class="wrap">' + sec_head("दूसरे मंदिरों की दर्शन गाइड") + more + "</div></section>" +
            faq_html(g["faqs"]) + (DG_JS if g["live"] else ""))
    addr = {"@type": "PostalAddress", "addressLocality": g["city"], "addressRegion": g["region"], "addressCountry": "IN"}
    temple = {"@type": "HinduTemple", "name": g["name"], "address": addr}
    if g["official"]: temple["sameAs"] = [g["official"]]
    ld = [{"@type": "Article", "headline": g["h1"], "inLanguage": "hi", "author": {"@id": SITE + "#organization"},
           "publisher": {"@id": SITE + "#organization"}, "dateModified": TODAY, "description": g["desc"], "about": temple},
          faq_ld(g["faqs"])]
    add(g["slug"], g["title"], g["desc"], body, crumbs=g["short"] + " दर्शन", ld=ld, active="live-darshan.html")
    _dg_built.append(g)

